mapper.insert:
insert into recommendation_serve_sessions (
    id, actor_key, kind, query_hash, snapshot_json, created_at, expires_at
) values (
    #{id}, #{actorKey}, #{kind}, #{queryHash}, #{snapshotJson}, #{createdAt}, #{expiresAt}
)

mapper.select:
select id, actor_key, kind, query_hash, snapshot_json, created_at, expires_at
from recommendation_serve_sessions
where id = #{sessionId}

select request_hash, response_status, response_json, expires_at
from recommendation_client_requests
where actor_key = #{actorKey}
  and endpoint = #{endpoint}
  and client_request_id = #{clientRequestId}

mapper.insert:
insert into recommendation_client_requests (
    actor_key, endpoint, client_request_id, request_hash,
    response_status, response_json, expires_at
) values (
    #{actorKey}, #{endpoint}, #{clientRequestId}, #{requestHash},
    0, '', #{expiresAt}
)
on conflict (actor_key, endpoint, client_request_id) do nothing

merge into recommendation_client_requests target
using (values (
    #{actorKey}, #{endpoint}, #{clientRequestId}, #{requestHash}, #{expiresAt}
)) source(actor_key, endpoint, client_request_id, request_hash, expires_at)
on target.actor_key = source.actor_key
   and target.endpoint = source.endpoint
   and target.client_request_id = source.client_request_id
when not matched then
    insert (
        actor_key, endpoint, client_request_id, request_hash,
        response_status, response_json, expires_at
    )
    values (
        source.actor_key, source.endpoint, source.client_request_id,
        source.request_hash, 0, '', source.expires_at
    )

mapper.delete:
delete from recommendation_client_requests
where actor_key = #{actorKey}
  and endpoint = #{endpoint}
  and client_request_id = #{clientRequestId}
  and expires_at <= #{now}

mapper.update:
update recommendation_client_requests
set response_status = #{status},
    response_json = #{responseJson}
where actor_key = #{actorKey}
  and endpoint = #{endpoint}
  and client_request_id = #{clientRequestId}

mapper.select:
select event_fingerprint
from recommendation_client_events
where actor_key = #{actorKey}
  and event_id = #{eventId}

mapper.insert:
insert into recommendation_client_events (
    actor_key, event_id, event_fingerprint, event_type,
    entity_id, serve_session_id, occurred_at_ms
) values (
    #{actorKey}, #{eventId}, #{fingerprint}, #{type},
    #{entityId}, #{sessionId}, #{occurredAtMs}
)
on conflict (actor_key, event_id) do nothing

merge into recommendation_client_events target
using (values (
    #{actorKey}, #{eventId}, #{fingerprint}, #{type},
    #{entityId}, #{sessionId}, #{occurredAtMs}
)) source(
    actor_key, event_id, event_fingerprint, event_type,
    entity_id, serve_session_id, occurred_at_ms
)
on target.actor_key = source.actor_key
   and target.event_id = source.event_id
when not matched then
    insert (
        actor_key, event_id, event_fingerprint, event_type,
        entity_id, serve_session_id, occurred_at_ms
    )
    values (
        source.actor_key, source.event_id, source.event_fingerprint,
        source.event_type, source.entity_id, source.serve_session_id,
        source.occurred_at_ms
    )

mapper.update:
update recommendation_user_interests
set weight = weight + #{delta},
    updated_at = current_timestamp
where actor_key = #{actorKey}
  and interest_key = #{interestKey}

mapper.insert:
insert into recommendation_user_interests (
    actor_key, interest_key, weight
) values (
    #{actorKey}, #{interestKey}, #{weight}
)
on conflict (actor_key, interest_key) do nothing

merge into recommendation_user_interests target
using (values (
    #{actorKey}, #{interestKey}, #{weight}
)) source(actor_key, interest_key, weight)
on target.actor_key = source.actor_key
   and target.interest_key = source.interest_key
when not matched then
    insert (actor_key, interest_key, weight)
    values (source.actor_key, source.interest_key, source.weight)
